def lengthOfLIS(nums: List[int]) -> int:
    n = len(nums)
    max_len = 0
    for i in range(1 << n):
        subseq = []
        for j in range(n):
            if (i >> j) & 1:
                subseq.append(nums[j])
        is_increasing = True
        for k in range(1, len(subseq)):
            if subseq[k] <= subseq[k - 1]:
                is_increasing = False
                break
        if is_increasing:
            if len(subseq) > max_len:
                max_len = len(subseq)
    return max_len

